// Optional native preview. No provider request, asset download, iframe or automatic motion.
export function attachCinematic({host,signal,load=()=>import('./cinematic-world.mjs')}){
 const doc=host.ownerDocument;let world=null,disposed=false,generation=0;
 host.innerHTML='<h2>Procedural living world</h2><p>Original Frutiger and Frawgy procedural geometry, shaders and mascots. Separate from room placement; artist-world assets are excluded. Open explicitly; motion starts paused.</p><button type="button" data-cinema-open>Open 3D preview</button><button type="button" data-cinema-close disabled>Close 3D preview</button><label>Scene <select data-cinema-theme><option value="frutiger">Frutiger</option><option value="frawgy">Frawgy</option></select></label><label><input type="checkbox" data-cinema-motion> Animate scene</label><p role="status" data-cinema-status>Not loaded.</p><div data-cinema-view hidden></div>';
 const one=s=>host.querySelector(s),view=one('[data-cinema-view]'),status=one('[data-cinema-status]'),motion=one('[data-cinema-motion]'),open=one('[data-cinema-open]'),close=one('[data-cinema-close]');
 const media=doc.defaultView?.matchMedia?.('(prefers-reduced-motion: reduce)');
 function applyMotion(){if(disposed)return;const reduced=Boolean(media?.matches);if(reduced)motion.checked=false;motion.disabled=reduced||!world?.supported;world?.setMotion(Boolean(motion.checked)&&!reduced&&!doc.hidden);if(world?.supported)status.textContent=reduced?'3D ready; motion paused for reduced-motion preference.':motion.checked&&!doc.hidden?'3D ready; animation running.':'3D ready; animation paused.';}
 function stop(){generation++;world?.dispose();world=null;view.replaceChildren();view.hidden=true;motion.checked=false;motion.disabled=true;close.disabled=true;open.disabled=false;status.textContent='Preview closed; GPU resources released.';}
 open.addEventListener('click',async()=>{if(disposed||open.disabled)return;const token=++generation;open.disabled=true;close.disabled=false;status.textContent='Loading local 3D module…';try{const {CinematicWorld}=await load();if(disposed||token!==generation)return;view.hidden=false;world=new CinematicWorld(view);world.setTheme(one('[data-cinema-theme]').value);world.step(0);view.dataset.supported=String(world.supported);if(!world.supported){world.dispose();world=null;view.replaceChildren();view.hidden=true;status.textContent='WebGL unavailable. Room authoring is unaffected.';open.disabled=false;close.disabled=true;}else applyMotion();}catch(e){if(disposed||token!==generation)return;stop();status.textContent='3D preview unavailable. Room authoring is unaffected.';}});
 close.addEventListener('click',stop);motion.addEventListener('change',applyMotion);one('[data-cinema-theme]').addEventListener('change',()=>{if(world){world.setTheme(one('[data-cinema-theme]').value);world.step(0);}});
 media?.addEventListener?.('change',applyMotion);doc.addEventListener('visibilitychange',applyMotion);applyMotion();
 function dispose(){if(disposed)return;disposed=true;stop();media?.removeEventListener?.('change',applyMotion);doc.removeEventListener('visibilitychange',applyMotion);signal?.removeEventListener('abort',dispose);host.replaceChildren();}
 signal?.addEventListener('abort',dispose,{once:true});if(signal?.aborted)dispose();return {dispose};
}
